  (2, 'grant', 'grænt', 'n. 授予, 授予物, 允许；vt. 允许, 承认, 授与；授权命令', '来源：ECDICT 开源词库', 'n. any monetary aid；n. the act of providing a subsidy；n. (law) a transfer of property by deed of conveyance；n. Scottish painter; cousin of Lytton Strachey and member of the Bloomsbury Group (1885-1978)', '', 'n. 授予, 授予物, 允许；vt. 允许, 承认, 授与；授权命令', 'CET-6词库'),
  (2, 'repeat', 'ri''pi:t', 'n. 重复, 反复；vt. 重做, 重复, 复述, 使再现, 复制；vi. 重复；重复', '来源：ECDICT 开源词库', 'n. an event that repeats；v. to say, state, or perform again；v. to say again or imitate；v. do over', '', 'n. 重复, 反复；vt. 重做, 重复, 复述, 使再现, 复制；vi. 重复；重复', 'CET-6词库'),
  (2, 'insist', 'in''sist', 'v. 坚持, 坚决主张, 强调', '来源：ECDICT 开源词库', 'v. be emphatic or resolute and refuse to budge；v. assert to be true', '', 'v. 坚持, 坚决主张, 强调', 'CET-6词库'),
