  (2, 'wood', 'wud', 'n. 木材, 木制品；vt. 植林于, 给...添加木柴；vi. 收集木材', '来源：ECDICT 开源词库', 'n. the hard fibrous lignified substance under the bark of trees；n. United States film actress (1938-1981)；n. English conductor (1869-1944)；n. English writer of novels about murders and thefts and forgeries (1814-1887)', '', 'n. 木材, 木制品；vt. 植林于, 给...添加木柴；vi. 收集木材', 'CET-6词库'),
  (2, 'excellent', '''ekslәnt', 'a. 优良的, 杰出的, 出色的', '来源：ECDICT 开源词库', 's. very good; of the highest quality', '', 'a. 优良的, 杰出的, 出色的', 'CET-6词库'),
  (2, 'tour', 'tuә', 'n. 旅游, 观光旅行, 任期；vi. 旅行, 周游, 巡回；vt. 周游, 观光, 游历, 使巡回演出', '来源：ECDICT 开源词库', 'n. a journey or route all the way around a particular place or area；v. make a tour of a certain place', '', 'n. 旅游, 观光旅行, 任期；vi. 旅行, 周游, 巡回；vt. 周游, 观光, 游历, 使巡回演出', 'CET-6词库'),
  (2, 'interview', '''intәvju:', 'n. 面谈, 访问, 接见, 面试；vt. 接见, 对...进行面谈(试)', '来源：ECDICT 开源词库', 'n. the questioning of a person (or a conversation in which information is elicited); often conducted by journalists；v. conduct an interview in television, newspaper, and radio reporting；v. discuss formally with (somebody) for the purpose of an evaluation；', '', 'n. 面谈, 访问, 接见, 面试；vt. 接见, 对...进行面谈(试)', 'CET-6词库'),
  (2, 'launch', 'lɒ:ntʃ', 'n. 下水, 汽艇, 发射；vt. 使下水, 发射, 发动；vi. 起飞, 下水, 投入, 开始', '来源：ECDICT 开源词库', 'n. a motorboat with an open deck or a half deck；v. propel with force；v. launch for the first time; launch on a maiden voyage；v. get going; give impetus to', '', 'n. 下水, 汽艇, 发射；vt. 使下水, 发射, 发动；vi. 起飞, 下水, 投入, 开始', 'CET-6词库'),
  (2, 'consumer', 'kәn''sju:mә', 'n. 消费者；消费者, 用户', '来源：ECDICT 开源词库', 'n. a person who uses goods or services', '', 'n. 消费者；消费者, 用户', 'CET-6词库'),
  (2, 'promote', 'prәu''mәut', 'vt. 促进, 晋升, 创办, 推销；促进, 推广, 推销', '来源：ECDICT 开源词库', 'v. contribute to the progress or growth of；v. give a promotion to or assign to a higher position；v. be changed for a superior chess or checker piece；v. change a pawn for a better piece by advancing it to the eighth row, or change a checker piece for a mor', '', 'vt. 促进, 晋升, 创办, 推销；促进, 推广, 推销', 'CET-6词库'),
