  (2, 'audience', '''ɒ:diәns', 'n. 听众, 观众, 读者；听讼, 观众, 听众', '来源：ECDICT 开源词库', 'n. a gathering of spectators or listeners at a (usually public) performance；n. the part of the general public interested in a source of information or entertainment', '', 'n. 听众, 观众, 读者；听讼, 观众, 听众', 'CET-6词库'),
  (2, 'theatre', '', 'n. 戏院, 电影院, 剧场, 全体观众, 戏剧, 戏剧效果, 阶梯式讲堂, 场所', '来源：ECDICT 开源词库', 'n a building where theatrical performances or motion-picture shows can be presented；n the art of writing and producing plays；n a region in which active military operations are in progress', '', 'n. 戏院, 电影院, 剧场, 全体观众, 戏剧, 戏剧效果, 阶梯式讲堂, 场所', 'CET-6词库'),
  (2, 'prince', 'prins', 'n. 王子, 亲王, 国君, 贵族, 诸侯, 有权势的大人物', '来源：ECDICT 开源词库', 'n. a male member of a royal family other than the sovereign (especially the son of a sovereign)', '', 'n. 王子, 亲王, 国君, 贵族, 诸侯, 有权势的大人物', 'CET-6词库'),
  (2, 'crisis', '''kraisis', 'n. 危机, 危险期, 紧要关头；危象; 骤退, 临界, 极期', '来源：ECDICT 开源词库', 'n. an unstable situation of extreme danger or difficulty；n. a crucial stage or turning point in the course of something', '', 'n. 危机, 危险期, 紧要关头；危象; 骤退, 临界, 极期', 'CET-6词库'),
