  (2, 'respect', 'ri''spekt', 'n. 尊敬, 尊重, 问候；vt. 尊敬, 注意, 遵守', '来源：ECDICT 开源词库', 'n. (usually preceded by `in'') a detail or point；n. an attitude of admiration or esteem；v. regard highly; think much of；v. show respect towards', '', 'n. 尊敬, 尊重, 问候；vt. 尊敬, 注意, 遵守', 'CET-6词库'),
  (2, 'promise', '''prɒmis', 'n. 诺言, 约定的事情, 有指望；vt. 允诺, 约定, 预示；vi. 允诺, 有前途, 有指望', '来源：ECDICT 开源词库', 'n. a verbal commitment by one person to another agreeing to do (or not to do) something in the future；n. grounds for feeling hopeful about the future；v. make a promise or commitment；v. promise to undertake or give', '', 'n. 诺言, 约定的事情, 有指望；vt. 允诺, 约定, 预示；vi. 允诺, 有前途, 有指望', 'CET-6词库'),
  (2, 'magazine', '.mægә''zi:n', 'n. 杂志, 仓库, 弹盒, 胶卷盒；卡片箱, 介质装卸程序', '来源：ECDICT 开源词库', 'n. a periodic publication containing pictures and stories and articles of interest to those who purchase it or subscribe to it；n. product consisting of a paperback periodic publication as a physical object；n. a business firm that publishes magazines；n. a ', '', 'n. 杂志, 仓库, 弹盒, 胶卷盒；卡片箱, 介质装卸程序', 'CET-6词库'),
  (2, 'freedom', '''fri:dәm', 'n. 自由, 坦率, 特权；自由, 自主, 免除', '来源：ECDICT 开源词库', 'n. the condition of being free; the power to act or speak or think without externally imposed restraints', '', 'n. 自由, 坦率, 特权；自由, 自主, 免除', 'CET-6词库'),
  (2, 'formal', '''fɒ:mәl', 'a. 正式的, 形式的, 礼仪的, 拘于礼节的, 拘谨的；n. 正式的社交活动', '来源：ECDICT 开源词库', 'a. being in accord with established forms and conventions and requirements (as e.g. of formal dress)；s. characteristic of or befitting a person in authority；a. (of spoken and written language) adhering to traditional standards of correctness and without c', '', 'a. 正式的, 形式的, 礼仪的, 拘于礼节的, 拘谨的；n. 正式的社交活动', 'CET-6词库'),
  (2, 'writing', '''raitiŋ', 'n. 书写, 著作, 笔迹, 作品；书写', '来源：ECDICT 开源词库', 'n. the act of creating written works；n. the work of a writer; anything expressed in letters of the alphabet (especially when considered from the point of view of style and effect)；n. (usually plural) the collected work of an author；n. letters or symbols t', '', 'n. 书写, 著作, 笔迹, 作品；书写', 'CET-6词库'),
  (2, 'reject', 'ri''dʒekt', 'n. 被拒之人, 被弃之物, 不合格品, 次品；vt. 拒绝, 抵制, 否决, 驳回, 丢弃, 呕出', '来源：ECDICT 开源词库', 'v. refuse to accept or acknowledge；v. reject with contempt；v. refuse entrance or membership', '', 'n. 被拒之人, 被弃之物, 不合格品, 次品；vt. 拒绝, 抵制, 否决, 驳回, 丢弃, 呕出', 'CET-6词库'),
  (2, 'joint', 'dʒɒint', 'n. 连接处, 接合, 关节；a. 共同的, 联合的, 连接的, 合办的；vt. 连接, 接合, 使有接头；vi. 贴合, 长节', '来源：ECDICT 开源词库', 'n. (anatomy) the point of connection between two bones or elements of a skeleton (especially if it allows motion)；n. a disreputable place of entertainment；n. junction by which parts or objects are joined together；n. marijuana leaves rolled into a cigarett', '', 'n. 连接处, 接合, 关节；a. 共同的, 联合的, 连接的, 合办的；vt. 连接, 接合, 使有接头；vi. 贴合, 长节', 'CET-6词库'),
  (2, 'conservative', 'kәn''sә:vәtiv', 'a. 保守的, 守旧的, 有保存力的；防腐剂; 保存剂', '来源：ECDICT 开源词库', 'n. a person who is reluctant to accept changes and new ideas；n. a member of a Conservative Party；a. resistant to change；s. having social or political views favoring conservatism', '', 'a. 保守的, 守旧的, 有保存力的；防腐剂; 保存剂', 'CET-6词库'),
  (2, 'invite', 'in''vait', 'vt. 邀请, 请求, 引起, 招致；n. 邀请', '来源：ECDICT 开源词库', 'n. a colloquial expression for invitation；v. increase the likelihood of；v. invite someone to one''s house；v. ask someone in a friendly way to do something', '', 'vt. 邀请, 请求, 引起, 招致；n. 邀请', 'CET-6词库'),
  (2, 'challenge', '''tʃælindʒ', 'n. 挑战, 盘问；vt. 向...挑战, 要求, 怀疑；vi. 挑战, 对(证据等)表示异议', '来源：ECDICT 开源词库', 'n. a demanding or stimulating situation；n. a call to engage in a contest or fight；n. questioning a statement and demanding an explanation；n. a formal objection to the selection of a particular person as a juror', '', 'n. 挑战, 盘问；vt. 向...挑战, 要求, 怀疑；vi. 挑战, 对(证据等)表示异议', 'CET-6词库'),
  (2, 'youth', 'ju:θ', 'n. 年轻, 青年时代, 青年们, 青春；青年, 青年时期, 青春时期', '来源：ECDICT 开源词库', 'n. the time of life between childhood and maturity；n. early maturity; the state of being young or immature or inexperienced；n. an early period of development；n. the freshness and vitality characteristic of a young person', '', 'n. 年轻, 青年时代, 青年们, 青春；青年, 青年时期, 青春时期', 'CET-6词库'),
  (2, 'warn', 'wɒ:n', 'vt. 警告, 提醒, 通知；vi. 发出警告', '来源：ECDICT 开源词库', 'v. notify of danger, potential harm, or risk；v. admonish or counsel in terms of someone''s behavior；v. ask to go away；v. notify, usually in advance', '', 'vt. 警告, 提醒, 通知；vi. 发出警告', 'CET-6词库'),
  (2, 'dream', 'dri:m', 'n. 梦, 空想, 愿望；v. 做梦, 想象, 梦想', '来源：ECDICT 开源词库', 'n. a series of mental images and emotions occurring during sleep；n. imaginative thoughts indulged in while awake；n. a state of mind characterized by abstraction and release from reality；n. someone or something wonderful', '', 'n. 梦, 空想, 愿望；v. 做梦, 想象, 梦想', 'CET-6词库'),
  (2, 'victory', '''viktәri', 'n. 胜利, 战胜, 克服', '来源：ECDICT 开源词库', 'n. a successful ending of a struggle or contest', '', 'n. 胜利, 战胜, 克服', 'CET-6词库');

